mapper.select:
SELECT COUNT(*) FROM GE_MP_SCHE_S A JOIN GE_MP_PRCDOC_M B ON A.PRCDOC_UNQ_KY_VAL = B.PRCDOC_UNQ_KY_VAL
AND B.PPCD = #{PPCD}
AND B.PRCDOC_NO LIKE '%'||#{PRCDOC_NO}||'%'
AND B.PRCDOC_NM LIKE '%'||#{PRCDOC_NM}||'%'
WHERE 1 = 1
AND A.CHKPR_FNM = #{CHKPR_FNM}
AND A.CHCK_DY BETWEEN #{CHCK_DY_S} AND #{CHCK_DY_E}
